<?php

declare(strict_types=1);
require dirname(__DIR__) . '/config/bootstrap.php';
use App\Auth;
use App\Database;
Auth::requireLogin();
$pdo=Database::connection();
$currency=(string)env('CURRENCY','NGN');
$query=trim((string)($_GET['q']??''));
$categoryId=(int)($_GET['category']??0);
$categories=$pdo->query("SELECT c.id,c.name,COUNT(s.id) service_count FROM categories c LEFT JOIN services s ON s.category_id=c.id AND s.status=1 WHERE c.status=1 GROUP BY c.id,c.name HAVING service_count>0 ORDER BY c.sort_order,c.name")->fetchAll();
$sql="SELECT s.id,s.name,s.description,s.provider_type,s.selling_rate,s.min_quantity,s.max_quantity,s.refill,s.cancel,c.id category_id,c.name category FROM services s LEFT JOIN categories c ON c.id=s.category_id WHERE s.status=1";$params=[];
if($categoryId>0){$sql.=' AND s.category_id=:category';$params[':category']=$categoryId;}
if($query!==''){$sql.=" AND (s.name LIKE :q OR s.provider_type LIKE :q OR COALESCE(s.description,'') LIKE :q)";$params[':q']='%'.$query.'%';}
$sql.=' ORDER BY COALESCE(c.sort_order,0),c.name,s.name';$stmt=$pdo->prepare($sql);$stmt->execute($params);$services=$stmt->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Service Catalogue | SMM Panel</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><style>.service-card{transition:transform .15s ease,box-shadow .15s ease}.service-card:hover{transform:translateY(-2px);box-shadow:0 .5rem 1rem rgba(0,0,0,.08)!important}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand fw-semibold" href="/dashboard.php">SMM Panel</a><div class="d-flex gap-2"><a class="btn btn-outline-light btn-sm" href="/orders.php">My Orders</a><a class="btn btn-primary btn-sm" href="/wallet.php">Wallet</a></div></div></nav><main class="container py-4 py-lg-5"><div class="d-flex flex-column flex-lg-row justify-content-between align-items-lg-end gap-3 mb-4"><div><div class="text-primary fw-semibold small text-uppercase">Marketplace</div><h1 class="h2 mb-1">Service Catalogue</h1><p class="text-muted mb-0">Search, compare and order from the currently available services.</p></div><a class="btn btn-primary" href="/order.php"><i class="bi bi-plus-lg me-1"></i>New Order</a></div><form class="card border-0 shadow-sm mb-4" method="get"><div class="card-body"><div class="row g-2"><div class="col-lg-8"><div class="input-group input-group-lg"><span class="input-group-text bg-white"><i class="bi bi-search"></i></span><input class="form-control" name="q" value="<?=htmlspecialchars($query,ENT_QUOTES,'UTF-8')?>" placeholder="Search followers, likes, views, comments..."></div></div><div class="col-lg-3"><select class="form-select form-select-lg" name="category"><option value="0">All categories</option><?php foreach($categories as $category):?><option value="<?= (int)$category['id']?>" <?=$categoryId===(int)$category['id']?'selected':''?>><?=htmlspecialchars($category['name'])?> (<?= (int)$category['service_count']?>)</option><?php endforeach;?></select></div><div class="col-lg-1 d-grid"><button class="btn btn-dark btn-lg">Go</button></div></div></div></form><?php if(!$services):?><div class="card border-0 shadow-sm"><div class="card-body text-center py-5"><i class="bi bi-search fs-1 text-muted"></i><h4 class="mt-3">No matching services</h4><p class="text-muted">Try another search or choose a different category.</p><a href="/services.php" class="btn btn-outline-primary">Clear filters</a></div></div><?php else:?><div class="row g-3"><?php foreach($services as $service):?><div class="col-md-6 col-xl-4"><div class="card service-card h-100 border-0 shadow-sm"><div class="card-body p-4 d-flex flex-column"><div class="d-flex justify-content-between gap-2 mb-3"><span class="badge text-bg-light border"><?=htmlspecialchars($service['category']??'Uncategorized')?></span><span class="badge text-bg-secondary"><?=htmlspecialchars($service['provider_type'])?></span></div><h5 class="card-title"><?=htmlspecialchars($service['name'])?></h5><?php if(!empty($service['description'])):?><p class="card-text text-muted small"><?=htmlspecialchars($service['description'])?></p><?php endif;?><div class="row g-2 small mb-3"><div class="col-6"><div class="bg-light rounded p-2"><span class="text-muted d-block">Rate / 1K</span><strong><?=htmlspecialchars($currency)?> <?=number_format((float)$service['selling_rate'],4)?></strong></div></div><div class="col-6"><div class="bg-light rounded p-2"><span class="text-muted d-block">Quantity</span><strong><?=number_format((int)$service['min_quantity'])?>–<?=number_format((int)$service['max_quantity'])?></strong></div></div></div><div class="mb-3"><?php if((int)$service['refill']===1):?><span class="badge text-bg-success me-1">Refill</span><?php endif;?><?php if((int)$service['cancel']===1):?><span class="badge text-bg-warning">Cancel</span><?php endif;?></div><a class="btn btn-primary mt-auto" href="/order.php?service=<?= (int)$service['id']?>">Order this service <i class="bi bi-arrow-right ms-1"></i></a></div></div></div><?php endforeach;?></div><?php endif;?></main></body></html>
